from author_common import *
G=['godbillonvey1971invariant']
items(236,[
I('P000370','construction','The Godbillon–Vey three-class',r'For an integrable defining one-form \(\omega\), choose \(\omega_1,\omega_2\) with \(d\omega=\omega\wedge\omega_1\), \(d\omega_1=\omega\wedge\omega_2\); the closed form \(\Omega=\omega\wedge\omega_1\wedge\omega_2\) defines a choice-independent class.',r'For a smooth cooriented codimension-one foliation, take a nowhere-vanishing defining form \(\omega\) and a one-form \(\eta\) with \(d\omega=\omega\wedge\eta\). The form \(\eta\wedge d\eta\) is closed and its de Rham class is independent of the choices. With the notebook convention, \(\Omega=-\eta\wedge d\eta\); this overall sign must be fixed when comparing numerical invariants.',r'\citet[\S1]{godbillonvey1971invariant} introduced the class in the issue dated 12 July 1971. Bernstein’s 20 September report is therefore exposition of a published result, not a later 1972 discovery.',r'the smooth construction is established. Compactness is needed to integrate over a fundamental cycle, not to define the cohomology class.',publication_match='exact',refs=G),
I('P000370','claim','Vanishing for a foliation by fibres',r'The class is zero when the foliation is a fibration.',r'For a cooriented codimension-one foliation given by the fibres of a smooth submersion onto an oriented one-dimensional manifold, a nowhere-zero closed defining one-form can be chosen by pulling back a one-form on the base. Taking \(\eta=0\) makes the Godbillon--Vey form zero.',r'This is a special case of \citet[\S2(i)]{godbillonvey1971invariant}: a nonsingular closed Pfaffian defining form gives zero class. The result predates the talk.',r'the fibre-foliation assertion is established with the indicated global defining-form hypothesis.',refs=G),
I('P000370','claim','Deformation invariance versus foliated concordance',r'The notebook says \ru{устойчив при деформ.}, stable under deformations, with no qualification on the deformation.',r'The Godbillon--Vey class is natural and invariant under a foliated concordance on \(M\times[0,1]\) transverse to the boundary. It need not be constant along an arbitrary smooth parameter family of foliations on \(M\). Thurston’s polygon construction yields foliations of \(S^3\) whose integrated classes vary as \(4\pi\operatorname{Area}(P)\), up to orientation convention.',r'The original \citet[\S1(iii)]{godbillonvey1971invariant} uses differentiable homotopy of foliations, which must be interpreted in its foliation-theoretic sense. \citet[p.~513]{thurston1972noncobordant}, communicated 15 December 1971 and published in 1972, demonstrates variable values. This refutes an unrestricted reading of the notebook.',r'unrestricted deformation invariance is false. A path of integrable plane fields is weaker than an integrable foliation on the product giving a concordance.',**{'class':'B'},literal_correctness='false as written',publication_match='exact',refs=G+['thurston1972noncobordant']),
I('P000370','construction','The nonzero homogeneous example on a compact SL2 quotient',r'The page sketches a compact quotient of \(SL_2(\mathbb R)\) by a discrete subgroup and the foliation by triangular-subgroup orbits, asserting dense trajectories and a nonzero class.',r'For a cocompact lattice \(\Gamma\subset SL_2(\mathbb R)\), the foliation on \(\Gamma\backslash SL_2(\mathbb R)\) associated to a two-dimensional Borel subgroup has a Godbillon--Vey form which is a nonzero invariant volume form. Hence its integral, with an orientation, is nonzero. Left/right quotient and invariant-form conventions must be made compatible.',r'This is Roussarie’s example recorded explicitly in \citet[\S2(iii)]{godbillonvey1971invariant}. Thus the nonzero example was published before Bernstein’s report. The page’s separate density assertion is not required for computing the class.',r'the homogeneous nonvanishing is established. The word ``always'' about density is meaningful only with the compact quotient and the intended connected orbit foliation fixed; it is not a statement for every discrete subgroup.',refs=G),
I('P000370','method','Transverse pseudogroups and formal vector-field characteristic classes',r'Local submersions \(\varphi_i\) give transition maps on intervals; because they form a pseudogroup rather than a single finite-dimensional group, the talk turns to \(W_1\), formal vector fields on the line.',r'A codimension-one foliation admits a Haefliger cocycle \(\varphi_j=\psi_{ji}\circ\varphi_i\) on sufficiently small overlaps, where the \(\psi_{ji}\) are local diffeomorphisms of intervals. Formal transverse jets yield a characteristic homomorphism from the appropriate continuous formal-vector-field cohomology to de Rham cohomology of the foliated manifold.',r'The original \citet[\S3]{godbillonvey1971invariant} constructs a universal Lie coalgebra for this purpose. The broader formal-coordinate construction is developed in the contemporary \citet{gelfandkazhdan1971geometry} and is discussed in record 243.',r'this is an established source of secondary foliation classes. The raw composition \(\varphi_j\varphi_i\) on the page is not defined; the overlap factorization is the correct relation.',reconstruction=r'The term Haefliger cocycle and the explicit factorization specify the modern meaning of the sketch.',refs=G+['gelfandkazhdan1971geometry']),
I('P000370','theorem','The continuous cohomology of W1',r'The page says the cohomology vanishes except for \(H^3(W_1;\mathbb R)=\mathbb R\), identifying that generator with the preceding class.',r'For the Lie algebra \(W_1\) of formal vector fields in one variable with its formal topology and trivial coefficients, continuous cohomology is one-dimensional in degrees 0 and 3 and zero in other degrees. The degree-three generator induces the Godbillon--Vey class under the characteristic map.',r'The formal-vector-field computation belongs to \citet{gelfandfuchs1970formal}; \citet[\S3]{godbillonvey1971invariant} identifies the foliation class. The missing degree-zero copy is an omitted standard qualification.',r'the cohomology statement is established for continuous cochains. It does not assert the same result for arbitrary discontinuous algebraic cochains.',refs=['gelfandfuchs1970formal']+G)
])
A=['atiyahpatodisinger1976spectral3']
items(237,[
I('P000370','theorem','Discrete spectrum of a self-adjoint elliptic operator',r'On a compact manifold, a self-adjoint elliptic differential operator has a discrete real spectrum, with positive and negative eigenvalues.',r'On a closed smooth manifold, a formally self-adjoint elliptic differential operator of positive order on a Hermitian vector bundle has a self-adjoint realization with compact resolvent. Its eigenvalues are real, have finite multiplicities, and accumulate only at infinity. There need not be infinitely many eigenvalues of both signs; boundary problems require boundary conditions.',r'These spectral facts are older elliptic theory, used as preliminaries in \citet[\S2]{atiyahpatodisinger1976spectral3}; the 1976 paper is a verification source, not their first publication.',r'the assertion is established with closedness or an appropriate elliptic boundary realization. Two-sided unbounded spectrum is an additional condition relevant to nontrivial loop examples.',refs=A),
I('P000370-P000371','definition','Spectral flow for a closed self-adjoint family',r'The eigenvalues move with \(t\), and the net number passing zero defines an integer. The family is periodic or closes by \(D_{t+1}=UD_tU^{-1}\).',r'A continuous loop of self-adjoint Fredholm operators, in a topology supporting continuous spectral projections near zero, has an integer spectral flow counting negative-to-positive crossings with sign. For smooth elliptic families, it is invariant under homotopies of loops. For open paths, endpoint conditions or a specified endpoint convention are required.',r'\citet[\S7, pp.~93--94]{atiyahpatodisinger1976spectral3} defines and studies this invariant; the paper notes earlier joint work with Lusztig. The present September 1971 notebook is evidence of earlier seminar circulation; the published paper was received in January 1975 and appeared in 1976.',r'spectral flow is established and applies beyond compact-resolvent differential operators. It must not be identified with an unsigned count of crossings.',**{'class':'A'},publication_match='exact',refs=A),
I('P000371','construction','The unit spectral-flow example on the circle',r'The example is \(D_t=-i\,d/dx+t\), with \(Uf=e^{ix}f\), and the recorded flow is \(\pm1\).',r'On the circle of length \(2\pi\), with periodic domain \(H^1\), the eigenvalues are \(n+t\), \(n\in\mathbb Z\). Over any unit interval with invertible endpoints, exactly one eigenvalue crosses upward, giving spectral flow \(+1\). Multiplication by \(e^{ix}\) satisfies \(UD_tU^{-1}=D_t-1\), so closure as written requires \(U=e^{-ix}\) or reversing the conjugation.',r'The same spectral model \(n+t\) is given in \citet[p.~94]{atiyahpatodisinger1976spectral3}. Its presence here is an early explicit example; the conjugation discrepancy is a faithful sign error in the notebook, independently checked by differentiating \(e^{-ix}f\).',r'the example is exact after a consistent orientation and gluing convention. The alternative \(\pm1\) records convention, whereas the displayed conjugation formula must actually be changed.',**{'class':'A'},literal_correctness='false as written',publication_match='exact',refs=A),
I('P000371','problem','Computing spectral flow from geometric data',r'The stated problem is to compute spectral flow from the manifold, operator, and gluing \(U\). The proposed answer is the index of \(P=\partial_t+D_t\) on the mapping torus.',r'Let \(D_t\) be a smooth family of self-adjoint first-order elliptic operators on the fibres of a smooth bundle over \(S^1\), acting on a compatibly glued Hermitian vector bundle. Then the suspended operator \(\partial_t+D_t\), with a connection in the parameter direction, is elliptic and \(\operatorname{sf}(D_t)=\operatorname{ind}(\partial_t+D_t)\). Equivalently spectral flow is the topological index of the family symbol. An arbitrary Hilbert-space unitary need not define such a geometric mapping torus.',r'\citet[Theorem 7.4 and pp.~94--95]{atiyahpatodisinger1976spectral3} proves precisely the topological formula and the first-order suspension equality, including a remark on nontrivial fibre bundles over the circle. This is a strong A identification, with 1971 circulation distinct from 1976 publication.',r'the geometric computation problem is solved under the stated elliptic and gluing hypotheses. The general Fredholm-loop invariant remains meaningful when a local differential mapping-torus model is unavailable.',**{'class':'A'},publication_match='exact',problem='GP-1971-04',refs=A),
I('P000371-P000372','method','Analytic eigenvalue branches and the orbit heuristic',r'Real-analytic dependence is used to label eigenvalues globally, and periodicity permutes their branches. Finite orbits and branches travelling towards the two infinities are used to read the integer. The bound \(|\lambda^{\prime}(t)|<C|\lambda(t)|\) is displayed.',r'For an analytic self-adjoint elliptic family with common domain and uniform elliptic estimates, local real-analytic eigenvalue branches can be continued along the real parameter. Their derivatives obey an estimate of the form \(|\lambda^{\prime}(t)|\le C(1+|\lambda(t)|)\) on compact parameter intervals. The notebook’s homogeneous bound forbids a nonzero derivative at a zero crossing and is contradicted by its own branch \(\lambda(t)=t\).',r'The later rigorous treatment in \citet[\S7]{atiyahpatodisinger1976spectral3} defines spectral flow through spectral graphs and perturbation, without requiring the informal orbit classification to carry the proof. The branch sketch is an antecedent, not a complete published argument.',r'the corrected analytic estimates support the spectral picture; the exact four-type orbit description needs hypotheses and is retained only as a heuristic. No general monotonicity of eigenvalues is implied.',**{'class':'A'},literal_correctness='false as written',publication_match='partial',refs=A),
I('P000372','method','The diagonal scalar-ODE model for the suspended index',r'Assuming eigenvectors independent of \(t\), the solutions are \(u_n(t)=c_n\exp(-\int\lambda_n)\). The notes use orbit counts for \(\ker P\) and \(\ker P^*\), and write \(\int_0^N\lambda_n(t)dt=0\) for a finite orbit.',r'In a diagonal model, \((\partial_t+\lambda(t))u=0\) gives \(u(t)=c\exp(-\int_0^t\lambda(s)ds)\). On a periodic orbit of length \(N\), a nonzero periodic solution exists exactly when the scalar monodromy is one; for real \(\lambda\), this is \(\int_0^N\lambda=0\). It is a condition, not an automatic identity. Such finite orbits contribute equally to kernel and cokernel. Infinite unfolded orbits require explicit square-integrability and gluing conditions.',r'The notebook labels the calculation heuristic and acknowledges extra terms from moving eigenvectors. The rigorous equality is \citet[pp.~94--95]{atiyahpatodisinger1976spectral3}; the displayed scalar model is only a special-case explanation.',r'the elementary ODE calculation is valid with its boundary conditions, but does not by itself prove the general spectral-flow theorem.',**{'class':'A'},literal_correctness='correct with missing hypotheses',publication_match='partial',refs=A),
I('P000373','claim','A diffeomorphism and the obstruction from a natural operator family',r'A diffeomorphism \(T:X\to X\), a metric, and a natural self-adjoint operator determine a family on the mapping torus. If \(T\) preserves a metric, the family is constant and its flow vanishes.',r'For a diffeomorphism-equivariant elliptic construction, compatible endpoint identification and a path of metrics give a closed operator family. If the spectral-flow class is independent of that path and an invariant metric exists, one may use the constant metric, so the invariant is zero. Consequently a verified nonzero value obstructs an invariant metric; the conclusion is conditional on the operator family actually having nonzero possible flow.',r'The mapping-torus extension appears in \citet[remark after Theorem 7.4]{atiyahpatodisinger1976spectral3}. The notebook’s geometric observation is a correct application of homotopy invariance, but its next choice \(d+\delta\) requires a separate audit.',r'the implication is valid for a suitably specified natural elliptic family. It does not establish that every suggested natural operator yields an effective obstruction.',**{'class':'A'},publication_match='partial',refs=A),
I('P000373','claim','The ungraded de Rham operator has zero spectral flow',r'The example offered for the preceding construction is \(d+\delta\) on forms. No chirality restriction or odd-signature modification is written.',r'On all differential forms, \(D_t=d_t+d_t^*\) anticommutes with degree parity \(\Gamma\omega=(-1)^{\deg\omega}\omega\). If the endpoint gluing preserves parity, a closed family is unitarily conjugate to its negative; spectral-flow invariance and sign reversal give \(\operatorname{sf}(D_t)=0\). A potentially nontrivial signature construction uses a different restricted or chirality-modified operator.',r'The general spectral-flow theorem is \citet[\S7]{atiyahpatodisinger1976spectral3}; its signature discussion in \S6 uses the appropriate signature operator. The notebook does not record the missing modification. The chapter’s grading-symmetry verification explains why its ungraded example cannot supply a nonzero obstruction.',r'the vanishing is an elementary consequence of parity symmetry. The intended nontrivial example cannot be recovered merely by citing the general index theorem.',**{'class':'F'},literal_correctness='false as written',publication_match='partial',refs=A,confidence='medium'),
I('P000373','remark','The incomplete higher-signature example',r'The page mentions characters \(\pi_1(X)\to\mathbb Z\to S^1\), \(X^{4k+1}\times S^1\), Novikov’s invariant, and Hirzebruch’s \(L\)-polynomial.',r'A family of flat line-bundle twists over a character circle can be paired with an odd elliptic symbol through an index theorem. The notes do not specify a signature-type operator, its grading, the twisting bundle on the product, or the precise cohomology pairing. Therefore no unique higher-signature formula follows from the recorded data.',r'\citet[\S\S5--7]{atiyahpatodisinger1976spectral3} provides related index formulas for flat bundles and signature operators. The match here is thematic, unlike the exact identification of item 1971-237.4. A dimensional or grading repair must not be silently attributed to Atiyah’s unrecorded speech.',r'the general subject is developed, but this particular compressed example remains incompletely identifiable. The literal \(d+\delta\) interpretation has the zero-flow limitation just explained.',**{'class':'F'},literal_correctness='not determinable',publication_match='thematic only',refs=A,confidence='low')
])
items(238,[I('P000373','remark','Motives and different cohomology theories: no recorded result',r'The entry reads Deligne, in Manin’s translation, on the theory of motives and different cohomology theories of algebraic varieties.',r'The text supports only this subject identification. It gives no category of motives, equivalence relation on algebraic cycles, realization functor, or conjectural comparison that could be made into a uniquely attributable theorem.',r'No specific publication is assigned. Attaching the Weil conjectures or a later motivic theory would fill a gap with information not contained in the notes.',r'the entry remains a subject notice; this is insufficient evidence for any claim about the fate of a particular mathematical problem.',**{'class':'F'},literal_correctness='not determinable',publication_match='none found',verification='unresolved lead',development='none',confidence='high')])
problems([{'id':'GP-1971-04','title':'Geometric computation of spectral flow','statement':r'For a closed family of self-adjoint elliptic operators, compute its signed eigenvalue flow from the family symbol and geometric gluing data; in first order, identify it with the index of the suspended mapping-torus operator.','occurrences':['1971-237.4'],'status':r'Solved in the elliptic setting by the topological-index formula and suspension equality of \citet[Theorem 7.4, pp.~94--95]{atiyahpatodisinger1976spectral3}. The notebook supplies September 1971 circulation evidence; publication followed in 1976. As of November 2026 the required hypotheses and distinction from arbitrary nonlocal unitary gluing are standard.','status_date':'2026-11','refs':A}])
